const co = require('co');
const fs = require('fs');
const _ = require('lodash');

const Util = require('@taf/taf-utils');
const Configure = Util.Config;

const logger = require('./logger');
const Registry = require('@taf/taf-registry');
const Communicator = require('@taf/taf-rpc').client;

Communicator.initialize();
if (!process.env.TAF_CONFIG) {
  Registry.setLocator('taf.tafregistry.QueryObj@tcp -h 172.16.11.37 -p 17890:tcp -h 172.16.8.122 -p 17890:tcp -h 172.16.8.123 -p 17890');
} else {
  Registry.setLocator(Communicator.getProperty("locator"));
}
Registry.setKeepAlive(true, 30000);

// 从主控获取注册表
const _queryEndpointsFromRegistry = function* (servant, lockName) {
  try {
    const ret = yield Registry.findObjectById4Any(servant);
    logger.lock.info(lockName, 'findObjectById4Any return', ret.response.return);
    logger.lock.info(lockName, 'findObjectById4Any costtime', ret.response.costtime);
    logger.lock.info(lockName, 'findObjectById4Any arguments.activeEp', ret.response.arguments.activeEp.toObject());
    logger.lock.info(lockName, 'findObjectById4Any arguments.inactiveEp', ret.response.arguments.inactiveEp.toObject());
    if (ret.response.return === 0) {
      return ret.response.arguments.activeEp.toObject();
    }
    logger.lock.info(lockName, 'threadLock-主控调用错误', ret.response);
    logger.timer.error(lockName, 'threadLock-主控调用错误', ret.response);
  } catch(err) {
    console.log(lockName, err);
    logger.lock.info(lockName, 'threadLock-主控调用异常', err);
    logger.timer.error(lockName, 'threadLock-主控调用异常', err);
  }
  return null;
};

const _getServantAndEndpoint = (app, server, port) => {
  const tafConfig = fs.readFileSync(process.env.TAF_CONFIG, 'utf8');
  const lines = tafConfig.split('\n').map(v => v.trim());
  let servant = null;
  let endpoint = null;
  for (const line of lines) {
    if (line.startsWith(`<${app}.${server}`)) {
      servant = line.replace(/Adapter|<|>/ig, '');
    } else if(line.startsWith('endpoint')) {
      if (servant && line.includes(`-p ${port} `)) {
        endpoint = line.replace('endpoint=', '');
        break;
      }
    }
  }
  // k8s环境serverPort和localPort无法匹配,servant默认按字典序倒序排列，取第一个protocol=taf的endpoint
  if(!servant || !endpoint) {
    for (const line of lines) {
      if (line.startsWith(`<${app}.${server}`)) {
        servant = line.replace(/Adapter|<|>/ig, '');
      } else if(line.startsWith('endpoint')) {
        endpoint = line.replace('endpoint=', '');
      } else if(line === 'protocol=taf') {
        break;
      }
    }
  }
  return { servant, endpoint };
}

const threadLock = function* (option) {
  let lockName = '';
  let whiteList = null;
  if (_.isObject(option)) {
    if (option.name) {
      lockName = option.name;
    }
    if (_.isArray(option.whiteList) && option.whiteList.length) {
      whiteList = option.whiteList;
      logger.lock.info(lockName, "已设置IP白名单:" + whiteList.join(","));
    }
  }
  // 非TAF环境只有一个线程,直接返回true
  if (!process.env.TAF_CONFIG) {
    logger.lock.info(lockName, "本地环境定时器直接执行");
    logger.lock.info(lockName, '加锁结果', true);
    return true;
  }
  let processIndex = process.env.PROCESS_INDEX;
  logger.lock.info(lockName, `进程${processIndex}开始执行定时器`);
  // 不是0号进程直接返回false
  if (processIndex !== '0') {
    logger.lock.info(lockName, `进程${processIndex}非0号进程,放弃加锁`);
    logger.lock.info(lockName, '加锁结果', false);
    return false;
  }
  // 从taf配置文件中读取参数
  const configure = new Configure();
  configure.parseFile(process.env.TAF_CONFIG);
  // configure.parseFile('./GX.GxSmartStare.config.conf');
  // 应用
  const app = configure.get('taf.application.server.app');
  logger.lock.info(lockName, 'app', app);
  // 服务
  const server = configure.get('taf.application.server.server');
  logger.lock.info(lockName, 'server', server);
  // 本地参数
  const local = configure.get('taf.application.server.local');
  logger.lock.info(lockName, 'local', local);
  const localArray = local.split(' ');
  logger.lock.info(lockName, 'localArray', localArray);
  // 端口
  let port;
  for(let i=0;i<localArray.length; i+=1) {
    const item = localArray[i];
    if(item === '-p') {
      port = localArray[i+1];
    }
  }
  logger.lock.info(lockName, 'port', port);

  const { servant, endpoint } = _getServantAndEndpoint(app, server, port);
  logger.lock.info(lockName, 'servant', servant);
  logger.lock.info(lockName, 'endpoint', endpoint);
  // console.log('servant', servant);
  if (!servant) {
    logger.lock.info(lockName, 'TAF_CONFIG中没有找到匹配的servant', process.env.TAF_CONFIG, app, server, port);
    logger.timer.error(lockName, 'TAF_CONFIG中没有找到匹配的servant', process.env.TAF_CONFIG, app, server, port);
    logger.lock.info(lockName, '加锁结果', false);
    return false;
  }
  const endpointArray = endpoint.split(' ');
  logger.lock.info(lockName, 'endpointArray', endpointArray);
  let endpointHost, endpointPort;
  for(let i=0;i<endpointArray.length; i+=1) {
    const item = endpointArray[i];
    if(item === '-h') {
      endpointHost = endpointArray[i+1];
    }
    if(item === '-p') {
      endpointPort = endpointArray[i+1];
    }
  }
  logger.lock.info(lockName, 'endpointHost', endpointHost);
  logger.lock.info(lockName, 'endpointPort', endpointPort);

  // 从主控获取注册表
  let endpoints = yield _queryEndpointsFromRegistry(servant, lockName);
  logger.lock.info(lockName, 'queryEndpointsFromRegistry', endpoints);
  if (endpoints === null) {
    logger.lock.info(lockName, 'queryEndpointsFromRegistry 结果为空,加锁失败');
    logger.lock.info(lockName, '加锁结果', null);
    return null;
  }
  if (!endpoints.length) {
    logger.lock.info(lockName, 'threadLock-可用Servant为空', servant, '启动后首次调用没有获取到属于正常现象，持续获取失败请查询主控状态及网络');
    logger.timer.error(lockName, 'threadLock-可用Servant为空', servant, '启动后首次调用没有获取到属于正常现象，持续获取失败请查询主控状态及网络');
    logger.lock.info(lockName, '加锁结果', 0);
    return 0;
  }
  if (whiteList) {
    // 过滤在白名单中的endpoint
    const filtered = endpoints.filter(endpoint => whiteList.includes(endpoint.host));
    if (filtered.length) {
      logger.lock.info(lockName, '白名单过滤后endpoints', filtered);
      endpoints = filtered;
    } else {
      logger.lock.info(lockName, '白名单没有匹配成功执行原逻辑');
    }
  }
  // 比较取出"最小"HOST+PORT(字典序)
  const minEndpoint = _.min(endpoints.map(endpoint => `${endpoint.host}:${endpoint.port}`));
  logger.lock.info(lockName, 'minEndpoint', minEndpoint);
  logger.lock.info(lockName, '${endpointHost}:${endpointPort}', `${endpointHost}:${endpointPort}`);

  const lockResult = `${endpointHost}:${endpointPort}` === minEndpoint;
  logger.lock.info(lockName, '加锁结果', lockResult);

  return lockResult;
}

module.exports = co.wrap(threadLock);
